  function switchRightColor(element, imgPath) {
    const container = element.parentElement;
    container.querySelectorAll('.spec-color-btn-item').forEach(el => el.classList.remove('active'));
    element.classList.add('active');

    const cardBox = element.closest('.spec-color-large-card');
    const img = cardBox.querySelector('.spec-color-target-img');
    img.style.opacity = 0;
    setTimeout(() => {
      img.src = imgPath;
      img.style.opacity = 1;
    }, 120);
  }
